INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (18, 22, 'theory', 'Quiz: Social Network');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 22, 0, 'Why are messages sharded by conversation hash and not by time?', '["The hash is faster", "Sharding by time sends all new messages to the last shard — a hot spot", "The law requires it", "Time cannot be stored"]', 1, 'A hash spreads writes evenly, while all messages of a conversation stay on one shard.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 22, 1, 'How is friendship stored?', '["Only in one user''s list", "In the lists of both users: the operation touches two shards and runs as a saga or with event delivery", "It is not stored", "In the browser cache"]', 1, 'The link is mutual, so the record is needed in both places.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 22, 2, 'How do you build a news feed that includes large communities?', '["Push to all followers", "A hybrid: posts from ordinary people are pushed, posts from large communities are mixed in at read time", "Always only on request", "Randomly"]', 1, 'Pushing a community post to millions of followers is too expensive.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 22, 3, 'Why are People You May Know recommendations computed ahead of time?', '["It is cheap", "Walking the graph is expensive: compute in batches from the event stream and serve from the cache", "There is no data", "It is forbidden"]', 1, 'Computing online for every request is too heavy; the result is stored for each user.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 22, 4, 'What should happen to a deleted post?', '["Nothing", "Deletion is propagated by an event to feeds, caches, and search, and also checked at display time", "It stays forever", "It moves to friends"]', 1, 'This way privacy and deletion are honored immediately, while cleanup runs in the background.');
